VALUES ('ee0e7327-3b9d-5e2f-a2c4-ceddb89c0934', 'phase-05-lesson-29-acid-properties-write-ahead-logging-wal-m', 5, 29, 'ACID Properties & Write-Ahead Logging (WAL) Mechanics', '- **Status**: `[State: Active | Complete Specification | Core]`
